// [OPUS-4.8] sq-1s2.1.3 — sync the canonical SPARQL → ZK gate-cost catalog into the
// site as a typed JSON the static export imports at build time (NO git/network needed
// at build).
//
// SOURCE OF TRUTH: bench/zk-compose/sparql_feature_catalog.json — the comprehensive
// SPARQL-1.1 feature → ZK-coverage + gate-cost catalog landed by sq-1s2.1.2 (#770). It
// is regenerated by bench/zk-compose/scripts/sparql_catalog.py (which JOINs every
// `covered` circuit_size from crates/sparq-zk-compose/tests/gate_count_snapshot.json,
// the regression-gated source of truth) and gated by
// crates/sparq-zk-compose/tests/sparql_catalog.rs — so the numbers can never drift and a
// gap NEVER carries a fabricated gate count.
//
// OUTPUT: site/src/data/zk-sparql-catalog.generated.json — a byte-for-meaning copy the
// /benchmarks/zk page renders. We COPY rather than symlink so the static export is
// self-contained and offline-buildable, exactly like sync-benchmarks.mjs. Re-running this
// script (it runs in `prebuild`) re-pulls the canonical file, so the page auto-reflects
// the catalog on every build.
//
// HONESTY: this script does NOT compute, round, relabel or fabricate any number — it is a
// pure copy of the canonical, regression-gated JSON. If the source is absent (a shallow
// clone / fork that does not include bench/), we KEEP whatever generated JSON was already
// committed rather than failing the build or inventing data — same posture as
// sync-benchmarks.mjs.
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(here, "..", "..");
const src = join(
  repoRoot,
  "bench",
  "zk-compose",
  "sparql_feature_catalog.json",
);
const out = join(here, "..", "src", "data", "zk-sparql-catalog.generated.json");

if (!existsSync(src)) {
  if (existsSync(out)) {
    console.warn(
      "[sync-zk-catalog] bench/zk-compose/sparql_feature_catalog.json not found — keeping the already-committed generated JSON (no fabrication).",
    );
    process.exit(0);
  }
  console.error(
    "[sync-zk-catalog] no canonical catalog source AND no existing generated JSON — cannot proceed.",
  );
  process.exit(1);
}

// Parse to validate it is well-formed JSON (a malformed source must fail the build, not
// be silently copied), then re-serialise so the committed copy is stable + diff-friendly.
const catalog = JSON.parse(readFileSync(src, "utf8"));
const count = Object.keys(catalog.queries ?? {}).length;
if (count === 0) {
  console.error("[sync-zk-catalog] catalog has no queries — refusing to write.");
  process.exit(1);
}

writeFileSync(out, JSON.stringify(catalog, null, 2) + "\n");
console.log(
  `[sync-zk-catalog] copied SPARQL→ZK catalog (${count} queries; covered ${
    catalog.summary?.covered ?? "?"
  }, partial ${catalog.summary?.partial ?? "?"}, gaps ${
    catalog.summary?.gaps ?? "?"
  }) → src/data/zk-sparql-catalog.generated.json`,
);
